#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long capacity;
    long long cost;
    Edge(int to, int rev, long long capacity, long long cost)
        : to(to), rev(rev), capacity(capacity), cost(cost) {}
};

struct CostFlow {
    int n;
    std::vector<std::vector<Edge>> graph;
    std::vector<std::pair<int, int>> positions;
    std::vector<long long> potential;
    std::vector<int> prev_node, prev_edge;
    std::vector<bool> visited;

    CostFlow(int nodes) : n(nodes) {
        graph.resize(n);
        potential.resize(n, 0);
        prev_node.resize(n);
        prev_edge.resize(n);
        visited.resize(n);
    }

    int add_edge(int u, int v, long long cap, long long cst) {
        int index = (int)positions.size();
        positions.emplace_back(u, (int)graph[u].size());
        graph[u].emplace_back(v, (int)graph[v].size(), cap, cst);
        graph[v].emplace_back(u, (int)graph[u].size() - 1, 0, -cst);
        return index;
    }

    Edge get_edge(int i) {
        auto [u, idx] = positions[i];
        auto &e = graph[u][idx];
        auto &re = graph[e.to][e.rev];
        return Edge(u, e.to, e.capacity + re.capacity, e.cost);
    }

    std::vector<Edge> all_edges() {
        std::vector<Edge> res;
        for (int i = 0; i < (int)positions.size(); ++i) {
            auto [u, idx] = positions[i];
            auto &e = graph[u][idx];
            auto &re = graph[e.to][e.rev];
            res.emplace_back(u, e.to, e.capacity + re.capacity, e.cost);
        }
        return res;
    }

    bool shortest_path(int s, int t) {
        std::vector<long long> dist(n, LLONG_MAX);
        std::fill(visited.begin(), visited.end(), false);
        for (int i = 0; i < n; ++i) {
            prev_node[i] = -1;
            prev_edge[i] = -1;
        }
        dist[s] = 0;
        using pli = std::pair<long long, int>;
        std::priority_queue<pli, std::vector<pli>, std::greater<pli>> heap;
        heap.emplace(0, s);
        while (!heap.empty()) {
            auto [d, v] = heap.top(); heap.pop();
            if (visited[v]) continue;
            visited[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)graph[v].size(); ++i) {
                auto &e = graph[v][i];
                if (e.capacity == 0 || visited[e.to]) continue;
                long long nd = d + e.cost + potential[v] - potential[e.to];
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    prev_node[e.to] = v;
                    prev_edge[e.to] = i;
                    heap.emplace(nd, e.to);
                }
            }
        }
        if (!visited[t]) return false;
        for (int v = 0; v < n; ++v) {
            if (visited[v]) {
                potential[v] += dist[v];
            }
        }
        return true;
    }

    std::vector<std::pair<long long, long long>> min_cost_flow(int s, int t, long long flow_limit = (1LL << 32) - 1) {
        long long flow = 0;
        long long total_cost = 0;
        std::vector<std::pair<long long, long long>> result;
        result.emplace_back(flow, total_cost);
        while (flow < flow_limit) {
            if (!shortest_path(s, t)) break;
            long long c = flow_limit - flow;
            for (int v = t; v != s; v = prev_node[v]) {
                auto &e = graph[prev_node[v]][prev_edge[v]];
                c = std::min(c, e.capacity);
            }
            for (int v = t; v != s; v = prev_node[v]) {
                auto &e = graph[prev_node[v]][prev_edge[v]];
                e.capacity -= c;
                graph[e.to][e.rev].capacity += c;
            }
            long long delta = -potential[s];
            flow += c;
            total_cost += c * delta;
            if (result.back().second == total_cost) {
                result.pop_back();
            }
            result.emplace_back(flow, total_cost);
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int a1, a2, a3;
    int b1, b2, b3;
    cin >> a1 >> a2 >> a3;
    cin >> b1 >> b2 >> b3;

    CostFlow g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);

    for (int i = 1; i <= 3; ++i) {
        for (int j = 4; j <= 6; ++j) {
            int cst = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, LLONG_MAX, cst);
        }
    }

    auto res = g.min_cost_flow(0, 7);
    long long ans1 = res.back().first;
    long long ans2 = std::min((long long)a1, (long long)b2) + std::min((long long)a2, (long long)b3) + std::min((long long)a3, (long long)b1);
    cout << ans1 << " " << ans2 << "\n";
    return 0;
}

